
using System.ComponentModel.DataAnnotations;

namespace DWS.Web.UI.Models.ViewModels;

// Holds the information required to reset a user's password.
public class ResetPasswordViewModel
{
    // Stores the user's email address from the reset link.
    [Required]
    [EmailAddress]
    public string Email { get; set; } = string.Empty;

    // Stores the password reset token generated by ASP.NET Core Identity.
    [Required]
    public string Token { get; set; } = string.Empty;

    // Requires the customer to enter a new password.
    [Required(ErrorMessage = "New password is required.")]
    [StringLength(100, MinimumLength = 8,
        ErrorMessage = "Password must be at least 8 characters long.")]
    [DataType(DataType.Password)]
    public string NewPassword { get; set; } = string.Empty;

    // Ensures the customer enters the same password again.
    [Required(ErrorMessage = "Please confirm your new password.")]
    [DataType(DataType.Password)]
    [Compare(nameof(NewPassword),
        ErrorMessage = "The passwords do not match.")]
    public string ConfirmPassword { get; set; } = string.Empty;
}
